+            +{overflow.length}
+          </button>
+          {overflowOpen && (
+            <ul
+              role="menu"
+              aria-label="More views"
+              className="arq-shell-panel arq-tab-strip__overflow"
+              style={{
+                position: 'absolute',
+                top: '100%',
+                right: 0,
+                zIndex: 3,
+                listStyle: 'none',
+                margin: 0,
+                padding: 'var(--arq-space-micro)',
+                border: '1px solid var(--arq-ui-line-default)',
+                borderRadius: 'var(--arq-radius-menu)',
