+      'desktop',
+    );
+    expect(resolveWorkspacePlatform({ widthPx: 1024, heightPx: 768, coarsePointer: false })).toBe(
+      'compact-desktop',
+    );
+    expect(resolveWorkspacePlatform({ widthPx: 1194, heightPx: 834, coarsePointer: true })).toBe(
+      'tablet-landscape',
